'use strict';

/**
 * 实现者自查脚本（草稿区，非交付物）：
 *   1) 以真实 `node src/server.js` 子进程启动服务；
 *   2) 用 curl 打通关键链路：新增 -> 改状态 -> 筛选/排序 -> 统计 -> 导出 -> 删除；
 *   3) 打印监听地址（确认只绑 127.0.0.1）与 Ctrl+C（SIGINT）退出行为。
 * 用法：node temp/实现者/selfcheck.js
 */

const { spawn, execFileSync } = require('node:child_process');
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..', '..');
const DATA_DIR = path.join(__dirname, 'run-data');
fs.rmSync(DATA_DIR, { recursive: true, force: true });
fs.mkdirSync(DATA_DIR, { recursive: true });
const DATA_FILE = path.join(DATA_DIR, 'tasks.json');
const PORT = '4188';
const BASE = `http://127.0.0.1:${PORT}`;

function log(title, content) {
  console.log(`\n===== ${title} =====`);
  if (content !== undefined) console.log(content);
}

function curl(args) {
  const out = execFileSync('curl', args, { encoding: 'utf8' });
  return out;
}

function curlPrint(desc, args) {
  const shown = ['curl', ...args].join(' ');
  const out = curl(args);
  log(desc, `$ ${shown}\n${out.trim()}`);
  return out;
}

async function waitForReady(child) {
  return new Promise((resolve, reject) => {
    let buffer = '';
    const timer = setTimeout(() => reject(new Error('等待服务启动超时')), 10000);
    child.stdout.on('data', (chunk) => {
      buffer += chunk.toString();
      if (buffer.includes('按 Ctrl+C 退出')) {
        clearTimeout(timer);
        resolve(buffer);
      }
    });
    child.stderr.on('data', (chunk) => { buffer += chunk.toString(); });
    child.on('exit', (code) => {
      clearTimeout(timer);
      reject(new Error(`服务提前退出，退出码 ${code}\n${buffer}`));
    });
  });
}

(async () => {
  const child = spawn(process.execPath, ['src/server.js'], {
    cwd: ROOT,
    env: { ...process.env, PORT, KANBAN_DATA_FILE: DATA_FILE },
    stdio: ['ignore', 'pipe', 'pipe'],
  });

  let banner;
  try {
    banner = await waitForReady(child);
    log('1. 启动服务：PORT=4188 KANBAN_DATA_FILE=… node src/server.js', banner.trim());

    let listenInfo = '';
    try {
      listenInfo = execFileSync('lsof', ['-nP', `-iTCP:${PORT}`, '-sTCP:LISTEN'], { encoding: 'utf8' });
    } catch (err) {
      listenInfo = `（lsof 不可用：${err.message}）`;
    }
    log('2. 监听地址核查（只应出现 127.0.0.1，不应出现 0.0.0.0/*）', listenInfo.trim());

    const page = curl(['-s', '-o', '/dev/null', '-w', '%{http_code} %{content_type}', `${BASE}/`]);
    log('3. GET / 页面', `$ curl -s -o /dev/null -w '%{http_code} %{content_type}' ${BASE}/\n${page}`);

    const blank = curlPrint('4. POST /api/tasks（空白标题应 400 TITLE_REQUIRED）', [
      '-s', '-w', '\nHTTP %{http_code}', '-X', 'POST', `${BASE}/api/tasks`,
      '-H', 'Content-Type: application/json',
      '-d', '{"title":"   "}',
    ]);
    if (!blank.includes('TITLE_REQUIRED')) throw new Error('空白标题未被拒绝');

    const created = JSON.parse(curl([
      '-s', '-X', 'POST', `${BASE}/api/tasks`,
      '-H', 'Content-Type: application/json',
      '-d', '{"title":"<script>alert(1)</script> 修复登录页","priority":"high","tags":["前端","紧急","前端"]}',
    ]));
    log('5. POST /api/tasks 新增（含 <script> 与重复标签）', JSON.stringify(created, null, 2));
    const id = created.task.id;

    const created2 = JSON.parse(curl([
      '-s', '-X', 'POST', `${BASE}/api/tasks`,
      '-H', 'Content-Type: application/json',
      '-d', '{"title":"写 README","tags":["文档"]}',
    ]));
    log('6. POST /api/tasks 新增第二条（默认优先级 medium）', JSON.stringify(created2.task, null, 2));

    curlPrint('7. PUT /api/tasks/:id 改状态为 doing', [
      '-s', '-X', 'PUT', `${BASE}/api/tasks/${id}`,
      '-H', 'Content-Type: application/json',
      '-d', '{"status":"doing"}',
    ]);

    curlPrint('8. GET /api/tasks?status=doing&tag=前端&q=script&sort=priority&order=desc 筛选+排序', [
      '-s', `${BASE}/api/tasks?status=doing&tag=%E5%89%8D%E7%AB%AF&q=script&sort=priority&order=desc`,
    ]);

    curlPrint('9. GET /api/tasks?sort=createdAt&order=asc 按创建时间正序（标题列表）', [
      '-s', `${BASE}/api/tasks?sort=createdAt&order=asc`,
    ]);

    curlPrint('10. GET /api/stats 统计', ['-s', `${BASE}/api/stats`]);

    const exportHeaders = curl(['-s', '-D', '-', '-o', '/dev/null', `${BASE}/api/export`]);
    log('11. GET /api/export 响应头（Content-Disposition）', exportHeaders.trim());
    curlPrint('    GET /api/export 响应体', ['-s', `${BASE}/api/export`]);

    curlPrint('12. GET /api/status', ['-s', `${BASE}/api/status`]);

    curlPrint('13. GET /api/unknown 未知路径应 404 NOT_FOUND', [
      '-s', '-w', '\nHTTP %{http_code}', `${BASE}/api/unknown`,
    ]);

    curlPrint('14. POST /api/tasks 非法 JSON 应 400 BAD_JSON', [
      '-s', '-w', '\nHTTP %{http_code}', '-X', 'POST', `${BASE}/api/tasks`,
      '-H', 'Content-Type: application/json', '-d', '{坏 json',
    ]);

    curlPrint('15. DELETE /api/tasks/:id', ['-s', '-w', '\nHTTP %{http_code}', '-X', 'DELETE', `${BASE}/api/tasks/${created2.task.id}`]);
    curlPrint('16. 删除后 GET /api/tasks（应剩 1 条）', ['-s', `${BASE}/api/tasks`]);

    log('17. 数据文件内容（原子写产物）', fs.readFileSync(DATA_FILE, 'utf8').trim());
    log('18. 数据目录内容（不应有 .tmp- 残留）', fs.readdirSync(DATA_DIR).join('\n'));
  } finally {
    const exited = await new Promise((resolve) => {
      child.on('exit', (code, signal) => resolve({ code, signal }));
      child.kill('SIGINT');
      setTimeout(() => resolve({ code: 'timeout', signal: 'SIGINT 未退出' }), 5000);
    });
    log('19. 发送 SIGINT（等价 Ctrl+C）后的退出情况', JSON.stringify(exited));
  }
})().catch((err) => {
  console.error('自查失败：', err);
  process.exit(1);
});

