        reject(httpError('PAYLOAD_TOO_LARGE', '请求体过大，最大允许 1MB'));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', (err) => reject(httpError('BAD_REQUEST', `读取请求体失败：${err.message}`)));
  });
}

